        if (!/^\+?[\d\s\-()]+$/.test(v)) {
          return 'Error: Phone may only contain digits, spaces, dashes, parentheses, and a leading +.';
        }
        const digits = v.replace(/\D/g, '');
        if (digits.length < 7 || digits.length > 15) {
          return 'Error: Phone must contain 7 to 15 digits.';
        }
        return '';
      },
    },
